42	  static constexpr uint16_t kCsrFcsr     = 0x003;
43	  static constexpr uint16_t kCsrMstatus  = 0x300;
44	  static constexpr uint16_t kCsrMie      = 0x304;
45	  static constexpr uint16_t kCsrMtvec    = 0x305;
46	  static constexpr uint16_t kCsrMscratch = 0x340;
47	  static constexpr uint16_t kCsrMepc     = 0x341;
48	  static constexpr uint16_t kCsrMcause   = 0x342;
49	  static constexpr uint16_t kCsrMtval    = 0x343;
50	  static constexpr uint16_t kCsrMip      = 0x344;
51	  static constexpr uint16_t kCsrMcycle   = 0xB00;
52	  static constexpr uint16_t kCsrMinstret = 0xB02;
53	  // Andes machine setup CSRs crt0 writes at boot (see hybrid_state_v1):
54	  // mcache_ctl enables the L1 I/D caches, mmisc_ctl holds misc machine config.
55	  static constexpr uint16_t kCsrMcacheCtl = 0x7CA;
56	  static constexpr uint16_t kCsrMmiscCtl  = 0x7D0;
57	
58	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
59	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
60	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
61	
62	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
63	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
64	
65	  static constexpr uint32_t kAbstractcsBusy        = hybrid::kAbstractcsBusy;
66	  static constexpr uint32_t kAbstractcsCmderrMask  = hybrid::kAbstractcsCmderrMask;
67	
68	  // mstatus extension-state field: FS (bits 14:13).
69	  // "Initial" (01) is the minimal enable the abstract FPR writes require.
70	  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
71	  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
72	
73	  static constexpr unsigned kPollIterations = kDmiPollIterations;
74	
75	  explicit ResumeDriver(DmiBus& bus) : bus_{bus} {}
76	
77	  void resume(const hybrid_state_v1& state)
78	  {
79	    if (state.magic != HYBRID_STATE_MAGIC)
80	      throw std::runtime_error("ResumeDriver::resume: bad magic");
81	    if (state.version != HYBRID_STATE_VERSION)
82	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
83	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
84	    if (state.priv == 2 || state.priv > 3)
85	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
86	
87	    // dmactive must transition 0->1 in its own write before any other
88	    // DMCONTROL bit is honored (RISC-V Debug Spec).
89	    bus_.write(kDmcontrol, kDmcontrolDmactive);
90	    request_halt();
91	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
92	
93	    // mstatus: enable FS so the following FPR abstract writes are accepted
94	    // (FS == Off disables the extension and the hart NACKs the writes). The
95	    // drained state.mstatus may legitimately carry FS at Off (e.g. an OS
96	    // context-switched the regs away before the trigger fired) -- gating the
97	    // write on the drained field skips the enable and silently NACKs every
98	    // subsequent FPR write. Always write mstatus when FP is in scope;
99	    // force-OR Initial when the drained field is Off. This enable is local
100	    // to the vsim phase; the state.mstatus written to the handoff file is
101	    // left unmodified.
102	    if (state.flags & HYBRID_FLAG_FP) {
103	      uint64_t enable_mstatus = state.mstatus;
104	      if ((enable_mstatus & kMstatusFsMask) == 0)
105	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
106	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
107	    }
108	
109	    // FPR restore (requires mstatus.FS enabled above): one abstract register
110	    // write per f-reg. Abstract-only by design, like every non-V register
111	    // block -- the Program Buffer is reserved for state the abstract command
112	    // space cannot reach.
113	    if (state.flags & HYBRID_FLAG_FP) {
114	      for (uint16_t i = 0; i < 32; ++i)
115	        write_64bit_register(regno_fpr(i), state.fpr[i]);
116	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
117	      // fallback scratch x5 is overwritten by the GPR loop below.
118	      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
119	    }
120	
121	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
122	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
123	    // in the drained privilege; M-mode states skip the write (prv already 3).
124	    // Before the GPR loop: a PB fallback would clobber scratch x5.
125	    if (state.priv != 3) {
126	      // L2 slice: with PMP implemented and no matching entry, every S/U
127	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
128	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
129	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
130	      // RV64. Tolerant writes: entries beyond what the hart implements
131	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
132	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
133	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
134	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
135	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
136	
137	      const uint64_t dcsr =
138	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
139	      write_csr_abstract_or_pb(kCsrDcsr,
140	                               (dcsr & ~uint64_t{0x3}) | state.priv);
141	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
142	      // silently measure the ROI in the wrong privilege. Verify and abort.
143	      const uint64_t got =
144	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
145	        & 0x3u;
146	      if (got != state.priv)
147	        throw std::runtime_error(
148	          "ResumeDriver::resume: engine does not implement privilege level "
149	          + std::to_string(state.priv)
150	          + " (dcsr.prv pinned to " + std::to_string(got)
151	          + "); pick an S/U-capable engine");
152	    }
153	
154	    // GPRs + DPC (after every CSR write whose PB fallback uses x5 as
155	    // scratch, so x5 is safe to overwrite): one abstract register write per
156	    // GPR.
157	    for (uint16_t i = 1; i < 32; ++i)
158	      write_64bit_register(regno_gpr(i), state.gpr[i]);
159	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
160	
161	    write_csr_tolerant(kCsrMtvec, state.mtvec);
162	
163	    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
164	    // register with no hardware side effects, legal to use inside a trap-free
165	    // ROI. Restore it so a value stashed before the handoff survives into the
166	    // vsim phase.
167	    write_csr_tolerant(kCsrMscratch, state.mscratch);
168	
169	    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
170	    // interrupt-free ROI envelope these are ordinary read/write registers, so a
171	    // value stashed before the handoff must survive into the vsim phase (same
172	    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
173	    // hardware-driven pending bits, or mtval on a core that hardwires it)
174	    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
175	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
176	    write_csr_tolerant(kCsrMepc,   state.mepc);
177	    write_csr_tolerant(kCsrMcause, state.mcause);
178	    write_csr_tolerant(kCsrMtval,  state.mtval);
179	    write_csr_tolerant(kCsrMie,    state.mie);
180	    write_csr_tolerant(kCsrMip,    state.mip);
181	
182	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
183	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
184	    // caches) but has no cache model, so without this the cycle engine resumes
185	    // at the ROI with caches at their reset default -- DISABLED -- and the
186	    // whole measured window runs uncached, inflating it severalfold. Tolerant
187	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
188	    // write as a no-op, and a drained 0 (caches were off) restores the reset
189	    // state, so this is always safe to issue.
190	    write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
191	    write_csr_tolerant(kCsrMmiscCtl,  state.mmisc_ctl);
192	
193	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
194	    // from QEMU1's drain value. Without this, vsim's local counter starts
195	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
196	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
197	    // overwrite here as the GPR loop already ran.
198	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
199	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
200	
201	    clear_cmderr_if_set();
202	    request_resume();
203	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
204	                   "ResumeDriver resume");
205	  }
206	
207	private:
208	  void request_halt()
209	  {
210	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
211	  }
212	
213	  void request_resume()
214	  {
215	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
216	  }
217	
218	  void write_64bit_register(uint16_t regno, uint64_t value)
219	  {
220	    write_register_abstract(bus_, regno, value);
221	  }
222	
223	  // Abstract-first CSR write with Program Buffer fallback.
224	  // Tries an abstract register write; if the DM signals cmderr, clears it,
225	  // stages the value in scratch_gpr via abstract GPR write, then executes a
226	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
227	  // to x5 (t0) which the GPR restore loop overwrites later.
228	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
229	                                 uint8_t scratch_gpr = 5)
230	  {
231	    write_64bit_register(regno_csr(csr), value);
232	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
233	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
234	    write_64bit_register(regno_gpr(scratch_gpr), value);
235	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
236	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
237	  }
238	
239	  // Write a CSR-addressable register and clear any cmderr the DM raised.
240	  // Used for CSRs whose abstract-access support may be implementation
241	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
242	  // remaining writes.
243	  void write_csr_tolerant(uint16_t csr, uint64_t value)
244	  {
245	    write_64bit_register(regno_csr(csr), value);
246	    clear_cmderr_if_set();
247	  }
248	
249	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
250	  // is rejected until the bits are W1C-cleared. We tolerate per-register
251	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
252	  // error before resuming so the hart isn't left in a stuck state.
253	  // B17: record the last observed non-zero cmderr and a clear count so a
254	  // partially-broken restore is observable via the public accessors
255	  // instead of silently swallowed.
256	  void clear_cmderr_if_set()
257	  {
258	    const auto status = bus_.read(kAbstractcs);
259	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
260	    if (code != 0u) {
261	      last_observed_cmderr_ = code;
262	      ++cmderr_clear_count_;
263	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
264	    }
265	  }
266	
267	  DmiBus& bus_;
268	  uint32_t last_observed_cmderr_ = 0;
269	  uint64_t cmderr_clear_count_   = 0;
270	
271	public:
272	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
273	  // at least one abstract write tripped a sticky cmderr the restore
274	  // tolerated by clearing. cmderr_clear_count() is the total number of
275	  // such clears across all calls into clear_cmderr_if_set() this run.
276	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
277	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
278	};
279	
280	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
281	// via an Abstract Command. Halts-and-reads contract: caller must have the
282	// hart in the halted state. Shared by StateDrain (drain at exit). If
283	// abstractcs.cmderr goes sticky after the command, the helper clears it and
284	// reports 0 rather than blocking the caller -- a missing CSR mirrors as zero
285	// instead of corrupting the adjacent field.
286	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
287	                                     const char* poll_label
288	                                       = "read_register_64")
289	  -> std::optional<uint64_t>
290	{
291	  using RD = ResumeDriver;
292	  bus.write(RD::kCommand,
293	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
294	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
295	  const auto status = bus.read(RD::kAbstractcs);
296	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
297	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
298	    return std::nullopt;
299	  }
300	  const uint64_t lo = bus.read(RD::kData0);
301	  const uint64_t hi = bus.read(RD::kData1);
302	  return lo | (hi << 32);
303	}
304	
305	inline auto read_register_64(DmiBus& bus, uint16_t regno,
306	                             const char* poll_label = "read_register_64")
307	  -> uint64_t
308	{
309	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
310	}
