  // failure and moves on -- a batched PB sweep could not. The Program Buffer
  // carries only what abstract commands cannot reach: the V data sweep and
  // the Tier-B vsetvl.
  hybrid::ResumeDriver driver(bus, v_scratch_gpa());
  driver.resume(*hybrid_input_state_);
}
